S = "Hakeem Force Academy"
QS = [
(S, "Who was the 3rd Prime Minister of Pakistan?", ["Chaudhry Muhammad Ali", "Muhammad Ali Bogra", "Khawaja Nazimuddin", "Hussain Shaheed Suhrawardy"], 1, "The order of Pakistan's early prime ministers was Liaquat Ali Khan, Khawaja Nazimuddin, Muhammad Ali Bogra, Chaudhry Muhammad Ali and H. S. Suhrawardy. So the third was Muhammad Ali Bogra.", "Muhammad Ali Bogra took office in April 1953 after Khawaja Nazimuddin was dismissed.", [5320]),
(S, "Who was the 5th Prime Minister of Pakistan?", ["Feroz Khan Noon", "Muhammad Ali Bogra", "Hussain Shaheed Suhrawardy", "Fazal Elahi Chaudhry"], 2, "The first five prime ministers were Liaquat Ali Khan, Nazimuddin, Bogra, Chaudhry Muhammad Ali and then H. S. Suhrawardy. Fazal Elahi Chaudhry was a President, not a Prime Minister.", "Suhrawardy served from September 1956 to October 1957 and was followed by I. I. Chundrigar.", [5322]),
(S, "What is 3x4 + 2x4 (also written 3x4 + 4x2)?", ["18", "24", "22", "20"], 3, "Multiply first: 3x4 = 12 and 2x4 = 8 (4x2 is also 8). Then add: 12 + 8 = 20.", "In arithmetic, multiplication is done before addition (BODMAS).", [3293, 3294]),
(S, "What is 4 + 4x4?", ["32", "20", "16", "24"], 1, "Multiplication comes first: 4x4 = 16. Then 4 + 16 = 20.", "Following BODMAS, 4 + 4x4 is not (4 + 4)x4 which would be 32.", [3295]),
(S, "What is one-fourth of 10% of 120?", ["3", "12", "30", "4"], 0, "10% of 120 = 12. One-fourth of 12 = 12 / 4 = 3.", "One-fourth of 120 itself is 30.", [3400]),
(S, "What is the transpose of a matrix of order 4x3?", ["4x3", "3x4", "4x4", "3x3"], 1, "The transpose swaps rows and columns, so a 4x3 matrix becomes a 3x4 matrix.", "The transpose of the transpose of a matrix gives back the original matrix.", [4027]),
(S, "How many columns does a matrix of order 5x4 have?", ["5", "9", "20", "4"], 3, "A matrix of order m x n has m rows and n columns. For 5x4 there are 5 rows and 4 columns.", "The total number of elements in a 5x4 matrix is 20.", [2357, 3852]),
(S, "If a helicopter covers 320 miles using 80 gallons of fuel, how many gallons are needed for 700 miles?", ["165", "170", "175", "180"], 2, "Fuel per mile = 80 / 320 = 0.25 gallons. For 700 miles: 700 x 0.25 = 175 gallons.", "Such questions are solved with direct proportion: more distance needs proportionally more fuel.", [2346]),
(S, "If the 28th day of a month is Monday, what day will be the 8th day of that month?", ["Sunday", "Monday", "Tuesday", "Wednesday"], 2, "From the 8th to the 28th is 20 days, and 20 = 2 weeks + 6 days. Going back 6 days from Monday gives Tuesday.", "Going back 6 days is the same as going forward 1 day in a week cycle.", [877]),
(S, "If the 2nd day of a month is Friday, what day will the 8th day be?", ["Thursday", "Friday", "Saturday", "Wednesday"], 0, "From the 2nd to the 8th is 6 days. Friday plus 6 days is Thursday.", "Six days after any day equals one day before it.", [2409]),
(S, "In a school of 3000 students, 2700 are present. What percentage of students are absent?", ["5%", "12%", "10%", "9%"], 2, "Absent = 3000 - 2700 = 300. Percentage = 300 / 3000 x 100 = 10%.", "Present students are 90% of the total.", [2361]),
(S, "Which prophet was sent to the nation (Qaum) of Aad?", ["Hazrat Hud (AS)", "Hazrat Salih (AS)", "Hazrat Shuaib (AS)", "Hazrat Lut (AS)"], 0, "Allah sent Hazrat Hud (AS) to guide the people of Aad, who lived in Al-Ahqaf in southern Arabia.", "Hazrat Salih (AS) was sent to the nation of Thamud.", [4865, 665]),
(S, "In which Hijri year was Aam-ul-Wafood (Year of Delegations)?", ["6 AH", "8 AH", "10 AH", "9 AH"], 3, "Delegations from many Arab tribes came to Madina to accept Islam in 9 AH, after the conquest of Makkah. This year is called Aam-ul-Wafood.", "The year 9 AH is also when the Battle of Tabuk took place.", [961]),
(S, "By which title is Hazrat Abdullah ibn Abbas (RA) well known?", ["Siddiq", "Tarjuman-ul-Quran", "Ghani", "Saifullah"], 1, "Abdullah ibn Abbas was a great scholar of Quranic interpretation, so he is called Tarjuman-ul-Quran (interpreter of the Quran). He is also called Hibr-ul-Ummah.", "Saifullah is the title of Hazrat Khalid bin Waleed (RA).", [1849]),
(S, "Who was Hazrat Abdullah bin Abbas (RA) in relation to the Holy Prophet (PBUH)?", ["Cousin", "Uncle", "Brother-in-law", "Foster brother"], 0, "He was the son of Hazrat Abbas (RA), the uncle of the Prophet (PBUH), so he was the Prophet's cousin.", "He was born about three years before the Hijrat.", [5302]),
(S, "What is the full form of OGRA in Pakistan?", ["Oil and Gas Regulatory Authority", "Oil and Gas Research Association", "Office of Gas and Rail Authority", "Oil and Gas Reserves Agency"], 0, "OGRA stands for Oil and Gas Regulatory Authority. It regulates the midstream and downstream oil and gas sector of Pakistan.", "OGRA was established in 2002.", [3456]),
(S, "At what age did Dr Abdul Qadeer Khan, the father of Pakistan's nuclear programme, die?", ["83", "85", "87", "80"], 1, "He was born on 1 April 1936 and died on 10 October 2021, which makes him 85 years old.", "He died in Islamabad and was buried in the H-8 graveyard.", [1779]),
(S, "For which field is Abdur Rehman Chughtai famous?", ["Painting", "Poetry", "Politics", "Cricket"], 0, "Abdur Rehman Chughtai (1894-1975) was a famous Pakistani painter and artist known for his Mughal-influenced style.", "He is also known for designing Pakistan's early postage stamps.", [816]),
(S, "What is the antonym of abhor?", ["Hate", "Despise", "Love", "Avoid"], 2, "To abhor means to hate strongly, so its opposite is to love or admire.", "Loathe and detest are synonyms of abhor.", [68, 3790]),
(S, "What is the meaning of abhor?", ["To admire", "To regret", "To forgive", "To hate strongly"], 3, "Abhor means to regard with disgust and hatred.", "The noun form is abhorrence.", [3541, 3744, 3790]),
(S, "What is the meaning (synonym) of abolish?", ["Establish", "Do away with", "Improve", "Delay"], 1, "To abolish a law or system means to formally put an end to it, which is to do away with it.", "Annul, scrap and repeal are other synonyms of abolish.", [3745, 3962]),
(S, "Which Surah of the Holy Quran is named after the ant?", ["Al-Baqarah", "Al-Ankabut", "An-Nahl", "An-Naml"], 3, "Surah An-Naml (Surah 27) is named after the ant that spoke to Hazrat Sulaiman (AS).", "Surah Al-Ankabut is named after the spider and An-Nahl after the bee.", [717]),
(S, "Who was Hazrat Halima Sadia (RA) in relation to the Holy Prophet (PBUH)?", ["Real mother", "Foster mother", "Grandmother", "Aunt"], 1, "Hazrat Halima Sadia of Banu Saad nursed and raised the infant Prophet (PBUH) in the desert, so she was his foster mother.", "The Prophet's real mother was Hazrat Amina.", [5388]),
(S, "In which year was the 1962 constitution of Pakistan abrogated?", ["1971", "1969", "1958", "1977"], 1, "General Yahya Khan took over after Ayub Khan resigned and abrogated the 1962 constitution in March 1969 by imposing martial law.", "The 1962 constitution had been introduced by Ayub Khan.", [2736]),
(S, "Who abrogated the 1962 constitution of Pakistan?", ["Ayub Khan", "Zia ul Haq", "Yahya Khan", "Iskander Mirza"], 2, "President Ayub Khan resigned in March 1969 and handed power to army chief General Yahya Khan, who abrogated the constitution.", "Yahya Khan ruled until December 1971.", [182]),
(S, "Who abrogated the 1956 constitution of Pakistan?", ["Iskander Mirza", "Ayub Khan", "Yahya Khan", "Ghulam Muhammad"], 0, "President Iskander Mirza abrogated the 1956 constitution on 7 October 1958 and imposed martial law.", "Ayub Khan, the army chief, removed Iskander Mirza only 20 days later.", [313]),
(S, "Who acts as the President of Pakistan in the absence of the President?", ["Prime Minister", "Chief Justice", "Chairman Senate", "Speaker of a Provincial Assembly"], 2, "Under Article 49 of the constitution, the Chairman of the Senate acts as President when the office is vacant or the President is absent.", "If the Chairman is unavailable, the Speaker of the National Assembly acts as President.", [448]),
(S, "Who among the companions accompanied the Holy Prophet (PBUH) during the Hijrat to Madina?", ["Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)", "Hazrat Uthman (RA)"], 1, "Hazrat Abu Bakr Siddiq (RA) accompanied the Prophet (PBUH) on the journey and stayed with him in the Cave of Thaur.", "Hazrat Ali (RA) stayed behind in Makkah to return the trusts of the people.", [4991]),
(S, "Who was the first among slaves to accept Islam, according to most Pakistani textbooks?", ["Hazrat Zaid bin Haritha (RA)", "Hazrat Bilal (RA)", "Hazrat Ammar (RA)", "Hazrat Khabbab (RA)"], 0, "Textbooks list Abu Bakr among men, Khadija among women, Ali among children and Zaid bin Haritha among freed slaves as the first to accept Islam.", "Some sources name Hazrat Bilal (RA) as the first slave to accept Islam, so sources differ.", [1391]),
(S, "How many acute angles are there in an acute triangle?", ["1", "3", "2", "0"], 1, "In an acute triangle all three angles are less than 90 degrees, so all three are acute.", "A right triangle has two acute angles and an obtuse triangle has two acute angles as well.", [833]),
(S, "What is a synonym of acute?", ["Mild", "Severe", "Blunt", "Slow"], 1, "Acute can mean sharp or intense, as in acute pain, and severe is the closest synonym.", "Acute angle means an angle less than 90 degrees.", [615]),
(S, "Insert the correct form of the verb: Lightning ____ across the bridge last night.", ["flash", "flashes", "flashed", "flashing"], 2, "The words last night show past time, so the simple past tense flashed is needed.", "The past participle of flash is also flashed.", [2773]),
(S, "Change to active voice: Why was the thief seen by Ali?", ["Why Ali saw the thief?", "Why did Ali see the thief?", "Why had Ali seen the thief?", "Why was Ali seeing the thief?"], 1, "The past simple passive was seen becomes did ... see in the active, with Ali as the subject and the thief as the object.", "In the active voice the doer of the action is the subject of the sentence.", [1885]),
(S, "When was the Indian Independence Act passed?", ["1935", "1947", "1946", "1949"], 1, "The Indian Independence Act was passed by the British Parliament in July 1947 and created the two dominions of India and Pakistan from 15 August 1947.", "It received royal assent on 18 July 1947.", [1250]),
(S, "In which year did Allama Iqbal deliver his famous Presidential Address at the Allahabad session of the Muslim League?", ["1930", "1928", "1940", "1937"], 0, "Allama Iqbal gave his Allahabad Address in 1930, in which he proposed a separate Muslim state in north-west India.", "He gave a series of lectures at Madras and other places in 1928-29, which became Reconstruction of Religious Thought in Islam.", [2684]),
(S, "On what date did Allama Iqbal deliver his Allahabad Address?", ["23 March 1930", "29 December 1930", "30 December 1930", "14 August 1930"], 1, "The Allahabad session of the All India Muslim League was held in December 1930 and Iqbal delivered his address on 29 December 1930.", "The idea of a separate Muslim state he gave there led to the Pakistan Resolution of 1940.", [2872]),
(S, "Which prophet confronted the king Namrood (Nimrod)?", ["Hazrat Musa (AS)", "Hazrat Ibrahim (AS)", "Hazrat Isa (AS)", "Hazrat Nuh (AS)"], 1, "Hazrat Ibrahim (AS) invited Namrood to worship one Allah, and Namrood had him thrown into a fire, which Allah made cool.", "Hazrat Musa (AS) was sent to Pharaoh (Firaun).", [3107]),
(S, "What is the antonym of accept?", ["Receive", "Reject", "Agree", "Admit"], 1, "To accept means to receive or agree to something, and its opposite is to reject or refuse.", "Decline and refuse are also antonyms of accept.", [3470]),
]
